0,"Create a web API function that utilizes the HTTP POST method to add a new resource and returns the newly created resource. The function should accept a request body containing the data for the new resource. Additionally, implement a function that uses the HTTP PATCH method to partially update an existing resource and returns the updated resource.",352,,"['```go
package main

import (
	""encoding/json""
	""net/http""

	""github.com/gorilla/mux""
)

type Resource struct {
	ID    int    `json:""id""`
	Name  string `json:""name""`
	Value string `json:""value""`
}

var resources []Resource
var nextID = 1

func createResource(w http.ResponseWriter, r *http.Request) {
	var newResource Resource
	err := json.NewDecoder(r.Body).Decode(&newResource)
	if err != nil {
		http.Error(w, ""Invalid request body"", http.StatusBadRequest)
		return
	}
	newResource.ID = nextID
	nextID++
	resources = append(resources, newResource)
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(newResource)
}

func updateResource(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	id := vars[""id""]
	var updatedFields Resource
	err := json.NewDecoder(r.Body).Decode(&updatedFields)
	if err != nil {
		http.Error(w, ""Invalid request body"", http.StatusBadRequest)
		return
	}
	for i, res := range resources {
		if strconv.Itoa(res.ID) == id {
			resources[i].Name = updatedFields.Name
			resources[i].Value = updatedFields.Value
			json.NewEncoder(w).Encode(resources[i])
			return
		}
	}
	http.Error(w, ""Resource not found"", http.StatusNotFound)
}

func main() {
	router := mux.NewRouter()
	router.HandleFunc(""/resources"", createResource).Methods(""POST"")
	router.HandleFunc(""/resources/{id}"", updateResource).Methods(""PATCH"")
	http.ListenAndServe("":8080"", router)
}
