0,"Write a Python function that accepts a CSV file path as input and checks if it contains the required columns: 'Name', 'Age', 'Gender', and 'Salary'. The function should return True if all the required columns are present in the CSV file, and False otherwise. Additionally, ensure that 'Age' is an integer, 'Gender' is either 'Male' or 'Female', and 'Salary' is a non-negative floating-point number.",798,,"[""```python
import csv

def check_csv_columns(file_path):
    required_columns = {'Name': str, 'Age': int, 'Gender': str, 'Salary': float}
    with open(file_path, mode='r') as file:
        reader = csv.DictReader(file)
        headers = reader.fieldnames
        if not all(column in headers for column in required_columns):
            return False

        for row in reader:
            if not isinstance(row['Age'], int) or row['Gender'] not in ['Male', 'Female'] or float(row['Salary']) < 0:
                return False

    return True
