import yaml

class YAMLHandler:
    _converters = {}

    @classmethod
    def register_converter(cls, key, func):
        cls._converters[key] = func

    @classmethod
    def convert_from_yaml(cls, yaml_data):
        data_dict = yaml.safe_load(yaml_data)
        for key, value in data_dict.items():
            if key in cls._converters:
                data_dict[key] = cls._converters[key](value)
        return data_dict

    @classmethod
    def from_dict(cls, data_dict):
        return cls(convert_from_yaml(data_dict))

