from itertools import islice

def fibonacci_sequence(n):
    a, b = 0, 1
    while a < n:
        yield a
        a, b = b, a + b

def sum_even_fibonacci(n):
    return sum(islice(filter(lambda x: x % 2 == 0, fibonacci_sequence(n)), None))

# Example usage:
n = 4000000
print(sum_even_fibonacci(n))
