import time
from collections import defaultdict

class TrieNode:
    def __init__(self):
        self.children = defaultdict(TrieNode)
        self.end_of_word = False
        self.count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            node = node.children[char]
            node.count += 1
        node.end_of_word = True

    def find_anagrams(self, words):
        anagram_counts = defaultdict(int)
        result_pairs = []

        start_time = time.time()

        for word in words:
            sorted_word = ''.join(sorted(word))
            if sorted_word not in anagram_counts:
                anagram_counts[sorted_word] += 1
                if anagram_counts[sorted_word] == 2:
                    result_pairs.append((word, words[anagram_counts[sorted_word]-1]))
                    anagram_counts[word] -= 1 # Remove the first occurrence to prevent double counting

        end_time = time.time()

        microseconds_taken = (end_time - start_time) * 10**6

        return result_pairs, microseconds_taken

def main():
    words_list = [""listen"", ""silent"", ""tinsel"", ""elints"", ""pots"", ""spot""]

    trie = Trie()

    for word in words_list:
        trie.insert(word)

    result, microseconds_taken= trie.find_anagrams(words_list)

    print(""Distinct Anagram Pairs:"")
    for pair in result:
        print(f""{pair[0]} and {pair[1]}"")

    print(f""\nNumber of microseconds taken: {microseconds_taken}"")

if __name__ == ""__main__"":
    main()
