import argparse
import os
import time
from collections import defaultdict

def extract_info(line):
    parts = line.strip().split(args.delimiter)
    return int(parts[args.sequence_number_index]), parts[-1]

def read_file(filename):
    try:
        with open(filename) as f:
            yield from f
    except IOError as e:
        print(f""Error reading {filename}: {e}"")
        return

def parse_timestamp(timestamp_str):
    try:
        return time.strptime(timestamp_str, args.timestamp_format)
    except ValueError as e:
        print(f""Invalid timestamp format: {timestamp_str}, {e}"")
        return None

def sort_and_extract_info(files):
    info_dict = defaultdict(list)

    for filename in files:
        for line in read_file(filename):
            seq_num, ts = extract_info(line)
            info_dict[seq_num].append((line.strip(), parse_timestamp(ts)))

    sorted_dict = dict(sorted(info_dict.items(), key=lambda x: x[0]))

    return sorted_dict

def main():
    parser = argparse.ArgumentParser(description=""Read files, sort lines based on sequence number,""
                                                 ""and optionally compare timestamps."")

    parser.add_argument(""files"", nargs=""+"", help=""Input filenames"")

    parser.add_argument(""-o"", ""--output"", help=""Output filename"")

    parser.add_argument(""-d"", ""--delimiter"", default=""."", help=""Sequence number delimiter"")

    parser.add_argument(""-t"", ""--timestamp_format"", default=""%Y-%m-%d %H:%M:%S"",
                        help=""Timestamp format (default: %Y-%m-%d %H:%M:%S)"")

    global args
    args = parser.parse_args()

    if args.output:
        output_file = open(args.output, 'w')
    else:
        output_file = None

    sorted_info = sort_and_extract_info(args.files)

    for seq_num, lines in sorted_info.items():
        for line, timestamp in lines:
            print(line, file=output_file)

    if args.output:
        output_file.close()

if __name__ == ""__main__"":
    main()
