0,"Create a Python function that takes a CSV file path as input. It should verify if the file contains the columns 'Name', 'Age', 'Gender', and 'Salary'. Return True if all required columns are present, and False otherwise. Validate that 'Age' is an integer, 'Gender' is either 'Male' or 'Female', and 'Salary' is a non-negative floating-point number.",798,,"[""```python
import csv

def validate_csv(file_path):
    with open(file_path, mode='r') as file:
        reader = csv.DictReader(file)
        required_columns = {'Name', 'Age', 'Gender', 'Salary'}

        if not required_columns.issubset(reader.fieldnames):
            return False

        for row in reader:
            try:
                age = int(row['Age'])
                salary = float(row['Salary'])
                gender = row['Gender']

                if not (isinstance(age, int) and isinstance(salary, float)):
                    return False

                if gender not in {'Male', 'Female'}:
                    return False

                if salary < 0:
                    return False
            except ValueError:
                return False

    return True
