0,"Create a Python function that takes a string representing the path of an Excel file and converts it into a JSON representation of the spreadsheet's data. The function should handle any exceptions that occur during the conversion process and return an error message if the file cannot be read or converted. Additionally, ensure that the JSON output preserves the structure and hierarchy of the original Excel file's data.",502,,"['```python
import json
from openpyxl import load_workbook

def excel_to_json(excel_path):
    try:
        workbook = load_workbook(excel_path)
        data = {}

        for sheet_name in workbook.sheetnames:
            sheet = workbook[sheet_name]
            sheet_data = []

            for row in sheet.iter_rows(values_only=True):
                sheet_data.append(row)

            data[sheet_name] = sheet_data

        return json.dumps(data, indent=4)
    except Exception as e:
        return f""Error: {str(e)}""

# Example usage
excel_path = 'path_to_your_excel_file.xlsx'
json_output = excel_to_json(excel_path)
print(json_output)
