from flask import Flask, request, jsonify, make_response
from flask_sqlalchemy import SQLAlchemy
from flask_limiter import Limiter
from flask_limiter.util import get_remote_address
from flask_caching import Cache
from functools import wraps
import logging

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///resources.db'
app.config['CACHE_TYPE'] = 'simple'

db = SQLAlchemy(app)
limiter = Limiter(
    app,
    key_func=get_remote_address,
    default_limits=[""200 per day"", ""50 per hour""]
)
cache = Cache(app)
logging.basicConfig(level=logging.INFO)

class Resource(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text)
    created_at = db.Column(db.DateTime, default=db.func.current_timestamp())
    tags = db.Column(db.JSON)

@app.route('/resource', methods=['POST'])
@limiter.limit(""5 per minute"")
def create_resource():
    data = request.get_json()
    new_resource = Resource(name=data['name'], description=data['description'], tags=data['tags'])
    db.session.add(new_resource)
    db.session.commit()
    return jsonify({'id': new_resource.id}), 201

@app.route('/resource/<int:id>', methods=['PATCH'])
@limiter.limit(""3 per minute"")
def update_resource(id):
    resource = Resource.query.get_or_404(id)
    data = request.get_json()
    for key, value in data.items():
        setattr(resource, key, value)
    db.session.commit()
    return jsonify({'id': resource.id}), 200

@app.route('/resource/<int:id>', methods=['DELETE'])
@limiter.limit(""1 per minute"")
def delete_resource(id):
    resource = Resource.query.get_or_404(id)
    db.session.delete(resource)
    db.session.commit()
    return make_response('', 204)

@app.route('/resources', methods=['GET'])
@limiter.limit(""50 per minute"")
@cache.cached(timeout=50)
def get_resources():
    page = request.args.get('page', default=1, type=int)
    per_page = request.args.get('per_page', default=10, type=int)
    sort_by = request.args.get('sort_by', default='created_at')
    direction = request.args.get('direction', default='asc').lower()
    query = Resource.query
    if 'tags' in request.args:
        tags = request.args['tags'].split(',')
        query = query.filter(Resource.tags.contains(tags))
    resources = query.order_by(getattr(Resource, sort_by).desc() if direction == 'desc' else getattr(Resource, sort_by).asc()).paginate(page=page, per_page=per_page)
    return jsonify([{'id': resource.id, 'name': resource.name, 'description': resource.description, 'created_at': resource.created_at, 'tags': resource.tags} for resource in resources.items])

@app.errorhandler(404)
def not_found_error(error):
    return make_response(jsonify({'error': 'Not found'}), 404)

@app.errorhandler(500)
def internal_error(error):
    db.session.rollback()
    return make_response(jsonify({'error': 'Internal server error'}), 500)

if __name__ == '__main__':
    app.run(debug=True)
```

