0,"Create a Python program that includes functions for generating, verifying, and decrypting digital signatures using the RSA and ECDSA algorithms. The program should take an input message, allow the user to choose between RSA and ECDSA for generating the signature, and return the hexadecimal representation of the generated signature. Additionally, provide a function to verify the authenticity of a received message's signature using either RSA or ECDSA. The program should also give users the option to include or exclude padding in the signature generation process based on their preferences.",347,,"['```python
from cryptography.hazmat.primitives.asymmetric import rsa, ec
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric.utils import Prehashed
from cryptography.exceptions import InvalidSignature

def generate_key_pair_rsa(key_size=2048):
    private_key = rsa.generate_private_key(
        public_exponent=65537,
        key_size=key_size,
    )
    return private_key, private_key.public_key()

def generate_key_pair_ecdsa(curve=ec.SECP256R1()):
    private_key = ec.generate_private_key(curve)
    return private_key, private_key.public_key()

def sign_message_rsa(message, private_key, padding=True):
    if padding:
        signature = private_key.sign(
            message,
            hashes.SHA256()
        )
    else:
        signature = private_key.sign(
            Prehashed(hashes.SHA256())
        )
    return signature.hex()

def sign_message_ecdsa(message, private_key, padding=True):
    if padding:
        signature = private_key.sign(
            message,
            ec.ECDSA(hashes.SHA256())
        )
    else:
        signature = private_key.sign(
            Prehashed(hashes.SHA256()),
            ec.ECDSA()
        )
    return signature.hex()

def verify_signature_rsa(message, signature, public_key, padding=True):
    try:
        if padding:
            public_key.verify(
                bytes.fromhex(signature),
                message,
                hashes.SHA256()
            )
        else:
            public_key.verify(
                Prehashed(bytes.fromhex(signature)),
                message,
                hashes.SHA256(),
                ec.ECDSA()
            )
        return True
    except InvalidSignature:
        return False

def verify_signature_ecdsa(message, signature, public_key, padding=True):
    try:
        if padding:
            public_key.verify(
                bytes.fromhex(signature),
                message,
                ec.ECDSA(hashes.SHA256())
            )
        else:
            public_key.verify(
                Prehashed(bytes.fromhex(signature)),
                message,
                ec.ECDSA(),
                hashes.SHA256()
            )
        return True
    except InvalidSignature:
        return False

# Example usage
message = b""Hello, world!""
private_rsa, public_rsa = generate_key_pair_rsa()
private_ecdsa, public_ecdsa = generate_key_pair_ecdsa()

signature_rsa_pad = sign_message_rsa(message, private_rsa)
signature_rsa_no_pad = sign_message_rsa(message, private_rsa, padding=False)

signature_ecdsa_pad = sign_message_ecdsa(message, private_ecdsa)
signature_ecdsa_no_pad = sign_message_ecdsa(message, private_ecdsa, padding=False)

print(""RSA Signature with Padding:"", signature_rsa_pad)
print(""RSA Signature without Padding:"", signature_rsa_no_pad)
print(""ECDSA Signature with Padding:"", signature_ecdsa_pad)
print(""ECDSA Signature without Padding:"", signature_ecdsa_no_pad)

# Verification
print(""Verification RSA with Padding:"", verify_signature_rsa(message, signature_rsa_pad, public_rsa))
print(""Verification RSA without Padding:"", verify_signature_rsa(message, signature_rsa_no_pad, public_rsa))
print(""Verification ECDSA with Padding:"", verify_signature_ecdsa(message, signature_ecdsa_pad, public_ecdsa))
print(""Verification ECDSA without Padding:"", verify_signature_ecdsa(message, signature_ecdsa_no_pad, public_ecdsa))
```']",1,[0],[],True,0,0,0,

