# Python Code for Validating the Integrity of a Text File Using SHA-256 Hashes

import hashlib
import logging

logging.basicConfig(filename='validation.log', level=logging.INFO)

def read_hashes_from_file(filename):
    hashes = {}
    with open(filename, 'r') as file:
        for line in file:
            parts = line.strip().split()
            if len(parts) == 2:
                hashes[parts[1]] = parts[0]
    return hashes

def validate_text_file(text_filename, hash_filename):
    text_hashes = {}
    with open(text_filename, 'r') as file:
        for line in file:
            sha256 = hashlib.sha256(line.encode()).hexdigest()
            text_hashes[line.strip()] = sha256

    hashes = read_hashes_from_file(hash_filename)

    with open(text_filename, 'r') as file:
        for line in file:
            original_line = line.strip()
            if original_line in hashes:
                stored_hash = hashes[original_line]
                computed_hash = text_hashes.get(original_line)
                if stored_hash != computed_hash:
                    logging.warning(f""Integrity check failed for line: {original_line}"")
                else:
                    logging.info(f""Line validated successfully: {original_line}"")
            else:
                logging.error(f""No hash found for line: {original_line}"")

if __name__ == ""__main__"":
    validate_text_file(""input.txt"", ""hashes.txt"")
