class MemoryManager:
    def __init__(self, array_size, initial_objects):
        self.array_size = array_size
        self.array = [None] * array_size
        self._initialize_array(initial_objects)

    def _initialize_array(self, initial_objects):
        for i in range(self.array_size):
            if not self.array[i]:
                if i < len(initial_objects):
                    self.array[i] = initial_objects[i]
                else:
                    self.array[i] = Object()

    def check_object(self, object_id, property_name):
        for obj in self.array:
            if obj and hasattr(obj, property_name) and getattr(obj, property_name) == object_id:
                return True
        return False

    def add_object(self, new_object):
        found = False
        for i in range(self.array_size):
            if not self.array[i]:
                self.array[i] = new_object
                found = True
                break

        if not found:
            print(""Array is full."")

    def display_objects(self):
        formatted_output = []
        for obj in self.array:
            if obj:
                properties_str = ', '.join([f""{k}: {v}"" for k, v in vars(obj).items()])
                formatted_output.append(f""{obj} -> {properties_str}"")

        print(""\n"".join(formatted_output))

