package main

import (
	""crypto/hmac""
	""crypto/sha256""
	""encoding/base64""
	""encoding/json""
	""fmt""
	""time""
)

type User struct {
	ID       string `json:""id""`
	Username string `json:""username""`
	Role     string `json:""role""`
}

type JWTClaims struct {
	User  User   `json:""user""`
	Exp   int64  `json:""exp""`
	Scope []string `json:""scope""`
}

func GenerateJWT(user User, secretKey string) (string, error) {
	expirationTime := time.Now().Add(5 * time.Minute).Unix()
	claims := JWTClaims{
		User: user,
		Exp:  expirationTime,
		Scope: []string{""read"", ""write""},
	}

	claimJSON, err := json.Marshal(claims)
	if err != nil {
		return """", err
	}

	hmacSHA256 := hmac.New(sha256.New, []byte(secretKey))
	hmacSHA256.Write(claimJSON)
	signature := base64.StdEncoding.EncodeToString(hmacSHA256.Sum(nil))

	token := fmt.Sprintf(""%s.%s.%s"", base64.RawURLEncoding.EncodeToString([]byte(claimJSON)), ""SignaturePlaceholder"", signature)
	return token, nil
}

func main() {
	user := User{
		ID:       ""123"",
		Username: ""johndoe"",
		Role:     ""admin"",
	}

	secretKey := ""your-256-bit-secret""
	token, err := GenerateJWT(user, secretKey)
	if err != nil {
		fmt.Println(""Error generating JWT:"", err)
		return
	}
	fmt.Println(""Generated JWT:"", token)
}
