def md5_digest(input_string):
    hash_object = hashlib.md5()
    hash_object.update(input_string.encode())
    return hash_object.hexdigest()

def sha_digest(input_string):
    hash_object = hashlib.sha256()
    hash_object.update(input_string.encode())
    return hash_object.hexdigest()

