import random
import string

def add_random_graph_elements(graph, vertex_count, edge_count):
    """"""
    Adds a specified number of random vertices and edges to the given graph.

    Parameters:
        graph (networkx.Graph): The graph to be modified.
        vertex_count (int): Number of random vertices to add.
        edge_count (int): Number of random edges to add.

    Returns:
        networkx.Graph: The updated graph after adding vertices and edges.
    """"""

    def generate_vertex_id():
        return ''.join(random.choices(string.ascii_lowercase, k=5))

    def add_vertex_properties(vertex):
        properties = {}
        for _ in range(random.randint(1, 3)):
            property_name = f""prop_{random.randint(100, 999)}""
            property_value = random.choice([""A"", ""B"", ""C""])
            properties[property_name] = property_value
        return properties

    def add_edge(source, dest):
        if source != dest:
            graph.add_edge(source, dest)

    for _ in range(vertex_count):
        new_vertex_id = generate_vertex_id()
        new_vertex_properties = add_vertex_properties(new_vertex_id)
        graph.add_node(new_vertex_id, **new_vertex_properties)

    for _ in range(edge_count):
        while True:
            source = random.choice(list(graph.nodes))
            dest = random.choice(list(graph.nodes))
            if source != dest:
                break
        add_edge(source, dest)

    return graph
