import argparse
from cryptography.fernet import Fernet

def generate_key():
    return Fernet.generate_key()

def load_key(filename):
    return open(filename, ""rb"").read()

def encrypt_message(key, message):
    f = Fernet(key)
    encrypted_message = f.encrypt(message.encode())
    return encrypted_message.decode()

def decrypt_message(key, encrypted_message):
    f = Fernet(key)
    decrypted_message = f.decrypt(encrypted_message.encode())
    return decrypted_message.decode()

if __name__ == ""__main__"":
    parser = argparse.ArgumentParser(description=""Cryptographic Algorithm Parser"")
    parser.add_argument(""algorithm"", choices=[""encrypt"", ""decrypt""], help=""Choose encryption or decryption"")
    parser.add_argument(""-k"", ""--key"", required=True, help=""Key for encryption/decryption"")
    parser.add_argument(""-m"", ""--message"", required=True, help=""Message to encrypt/decrypt"")
    args = parser.parse_args()

    if args.algorithm == ""encrypt"":
        print(encrypt_message(args.key, args.message))
    elif args.algorithm == ""decrypt"":
        print(decrypt_message(args.key, args.message))
