def find_mode(numbers):
    from collections import Counter
    if not numbers:
        return None
    count = Counter(numbers)
    max_count = max(count.values())
    mode = [num for num, freq in count.items() if freq == max_count]
    return mode[0] if len(mode) == 1 else ""No unique mode""

def find_smallest_positive(numbers):
    positive_numbers = [num for num in numbers if num > 0]
    if not positive_numbers:
        return None
    return min(positive_numbers)

def main():
    numbers = []
    print(""Enter floating-point numbers, enter 0 to finish input:"")

    while True:
        try:
            num = float(input())
            if num == 0:
                break
            numbers.append(num)
        except ValueError:
            print(""Please enter a valid number."")

    mode = find_mode([num for num in numbers if num != 0])
    smallest_positive = find_smallest_positive(numbers)

    try:
        print(f""The mode is: {mode}"")
    except TypeError as e:
        print(e)

    try:
        print(f""The smallest positive integer is: {smallest_positive}"")
    except TypeError as e:
        print(e)

if __name__ == ""__main__"":
    main()
