def calculate_averages(csv_file):
    identifier_values = {}

    with open(csv_file, mode='r') as file:
        reader = csv.reader(file)
        next(reader)  # Skip header row if present

        for row in reader:
            identifier = row[0]
            value = float(row[1])

            if identifier not in identifier_values:
                identifier_values[identifier] = {'sum': value, 'count': 1}
            else:
                identifier_values[identifier]['sum'] += value
                identifier_values[identifier]['count'] += 1

    averages = {id: total / count for id, stats in identifier_values.items() for total, count in [(stats['sum'], stats['count'])]}

    return averages

def save_averages_to_file(averages, output_file):
    with open(output_file, mode='w') as file:
        for identifier, average in averages.items():
            file.write(f""{identifier},{average}\n"")

if __name__ == ""__main__"":
    csv_input = 'input.csv'
    output_file = 'averages.txt'

    averages = calculate_averages(csv_input)
    save_averages_to_file(averages, output_file)
