import argparse

def parse_arguments():
    parser = argparse.ArgumentParser(description=""Text Analysis Tool"")
    parser.add_argument('-f', '--file', required=True, help='Input file path')
    parser.add_argument('-s', '--min_length', type=int, default=3, help='Minimum word length to filter (default: 3)')
    parser.add_argument('-o', '--output_file', help='Custom output file path')
    parser.add_argument('--unique_words', action='store_true', help='Analyze only unique words per line')
    return parser.parse_args()

def analyze_text(file_path, min_length, output_file, unique_words):
    with open(file_path, 'r') as file:
        lines = file.readlines()

    if unique_words:
        lines = [set(line.split()) for line in lines]

    filtered_lines = [line for line in lines if any(len(word) >= min_length for word in line)]

    if output_file:
        with open(output_file, 'w') as out_file:
            for line in filtered_lines:
                out_file.write(' '.join(line) + '\n')
    else:
        for line in filtered_lines:
            print(' '.join(line))

if __name__ == ""__main__"":
    args = parse_arguments()
    analyze_text(args.file, args.min_length, args.output_file, args.unique_words)
