        self.observations = observations

def generate_weather_stations(num_stations):
    stations = []
    for _ in range(num_stations):
        try:
            station_id = random.randint(1000, 9999)
            latitude = round(random.uniform(-85.051129, 85.051129), 6)
            longitude = round(random.uniform(-180, 180), 6)
            if random.random() < 0.3:
                observations = 10
            elif random.random() < 0.6:
