def find_mode(numbers):
    from collections import Counter
    counts = Counter(numbers)
    max_count = max(counts.values())
    mode_values = [num for num, count in counts.items() if count == max_count]
    return mode_values[0] if len(mode_values) == 1 else None

def find_smallest_positive(numbers):
    positive_numbers = [num for num in numbers if num > 0]
    return min(positive_numbers) if positive_numbers else None

def main():
    numbers = []
    sentinel_value = int(input(""Enter a sequence of decimal numbers (enter 0 to stop): ""))

    while sentinel_value != 0:
        numbers.append(sentinel_value)
        sentinel_value = int(input(""Enter the next number or 0 to stop: ""))

    if not any(numbers):
        print(""Error: No non-zero integers were entered."")
        return

    mode = find_mode(numbers)
    smallest_positive = find_smallest_positive(numbers)

    if mode is None:
        print(""No unique mode found among non-zero elements."")
    else:
        print(f""The mode is: {mode}"")

    if smallest_positive is None:
        print(""Error: No positive integers were entered."")
    else:
        print(f""The smallest positive integer is: {smallest_positive}"")

if __name__ == ""__main__"":
    main()
