import random
import logging

class WeatherStation:
    def __init__(self, id, latitude, longitude, observations):
        self.id = id
        self.latitude = latitude
        self.longitude = longitude
        self.observations = observations

def generate_weather_stations(num_stations, log_level):
    logging.basicConfig(level=log_level)
    stations = []
    try:
        for _ in range(num_stations):
            station_id = random.randint(1000, 9999)  # Random ID between 1000 and 9999
            latitude = random.uniform(-90.0, 90.0)  # Valid geographical latitude
            longitude = random.uniform(-180.0, 180.0)  # Valid geographical longitude
            if random.random() < 0.3:
                observations = 10
            elif random.random() < 0.6:
                observations = 25
            else:
                observations = 50
            stations.append(WeatherStation(station_id, latitude, longitude, observations))
        return stations
    except Exception as e:
        logging.error(f""Error generating weather stations: {e}"")
        return None

def main():
    try:
        num_stations = int(input(""Enter the number of weather stations to generate: ""))
        log_level = input(""Enter the log level (DEBUG, INFO, WARNING, ERROR, CRITICAL): "").upper()
        stations = generate_weather_stations(num_stations, log_level)
        if stations:
            for station in stations:
                print(f""Station ID: {station.id}, Latitude: {station.latitude}, Longitude: {station.longitude}, Observations: {station.observations}"")
    except ValueError as e:
        logging.error(f""Invalid input: {e}"")

if __name__ == ""__main__"":
    main()
