import argparse
import hashlib
import json
import os
import pickle

class CommandlineProcessor:
    def __init__(self):
        self.parser = argparse.ArgumentParser(description='CommandlineProcessor for file processing and MD5 hashing')
        self.parser.add_argument('input_file', help='Path to the input file')
        self.parser.add_argument('-o', '--output_file', help='Path to the output file')
        self.parser.add_argument('-s', '--state', action='store_true', help='Load and validate state object')
        self.parser.add_argument('-c', '--count_lines', action='store_true', help='Count lines in the input file')
        self.parser.add_argument('-h', '--hash_input', action='store_true', help='Compute MD5 hash for string input')

    def load_state(self, path):
        try:
            with open(path, 'rb') as f:
                state = pickle.load(f)
            return state
        except (pickle.UnpicklingError, FileNotFoundError):
            print(""Error: Failed to load or deserialize state object"")
            return None

    def validate_state(self, state):
        if not hasattr(state, 'validate'):
            print(""Error: State object does not have a 'validate' method"")
            return False
        if not state.validate():
            print(""Error: State object validation failed"")
            return False
        return True

    def process_input(self, args):
        if args.state:
            path = args.input_file
            state = self.load_state(path)
            if not state or not self.validate_state(state):
                exit(1)

        if args.count_lines:
            with open(args.input_file, 'r') as f:
                count = sum(1 for line in f)
                print(f""Number of lines in {args.input_file}: {count}"")

    def compute_md5_hash(self, text):
        hasher = hashlib.md5()
        hasher.update(text.encode('utf-8'))
        return hasher.hexdigest()

def main():
    processor = CommandlineProcessor()
    args = processor.parser.parse_args()

    if args.hash_input:
        text = input(""Enter text to compute MD5 hash: "")
        print(f""MD5 hash: {processor.compute_md5_hash(text)}"")

    processor.process_input(args)

if __name__ == '__main__':
    main()
