import random
from sympy import isprime

def generate_prime(min_range, max_range):
    while True:
        p = random.randint(min_range, max_range)
        if isprime(p):
            return p

def rsa_key_pair_gen(num_pairs, min_p_range, max_p_range):
    keys = []
    for _ in range(num_pairs):
        p = generate_prime(min_p_range, max_p_range)
        q = generate_prime(min_p_range, max_p_range)
        n = p * q
        phi_n = (p - 1) * (q - 1)
        e = random.randint(2, phi_n - 1)
        while True:
            gcd, d, _ = extended_gcd(e, phi_n)
            if gcd == 1 and d > 0:
                break
        keys.append((n, e, d))
    return keys

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    else:
        gcd, x, y = extended_gcd(b % a, a)
        return (gcd, y - (b // a) * x, x)

def test_key_pair(public_key, private_key, message):
    n, e, d = public_key
    d_n, e_n = private_key
    encrypted_message = pow(message, e, n)
    decrypted_message = pow(encrypted_message, d_n, n)
    return decrypted_message == message

def validate_private_key(private_key):
    n, _, d = private_key
    p, q = find_prime_factors(n)
    return n == p * q and (p - 1) * (q - 1) % d == 0

def find_prime_factors(n):
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return i, n // i
    raise ValueError(""No prime factors found"")

if __name__ == ""__main__"":
    try:
        num_pairs = int(input(""Enter the number of RSA key pairs to generate: ""))
        min_p_range = int(input(""Enter the minimum range for generating secure primes: ""))
        max_p_range = int(input(""Enter the maximum range for generating secure primes: ""))

        keys = rsa_key_pair_gen(num_pairs, min_p_range, max_p_range)
        print(f""Generated {num_pairs} RSA key pairs."")

        for i, (public_key, private_key) in enumerate(keys):
            if validate_private_key(private_key):
                message = random.randint(10, n - 1)
                if test_key_pair(public_key, private_key, message):
                    print(f""Key pair {i+1}: Valid and works correctly."")
                else:
                    print(f""Key pair {i+1}: Valid but encryption/decryption failed."")
            else:
                print(f""Key pair {i+1}: Invalid."")

    except ValueError as e:
        print(f""Error: {e}"")
```

