from mutagen.id3 import ID3, TIT2, TPE1, TALB, TCON

def extract_mp3_metadata(file_path):
    try:
        audio = ID3(file_path)
        metadata = {}

        if 'TIT2' in audio:
            metadata['title'] = audio['TIT2'].text[0]
        else:
            metadata['title'] = None

        if 'TPE1' in audio:
            metadata['artist'] = audio['TPE1'].text[0]
        else:
            metadata['artist'] = None

        if 'TALB' in audio:
            metadata['album'] = audio['TALB'].text[0]
        else:
            metadata['album'] = None

        if 'TCON' in audio:
            metadata['genre'] = audio['TCON'].text[0]
        else:
            metadata['genre'] = None

        return metadata

    except FileNotFoundError:
        print(f""Error: The file '{file_path}' does not exist."")
        return None

    except Exception as e:
        print(f""An error occurred while reading the MP3 file: {e}"")
        return None
