def get_mode(numbers):
    from collections import Counter
    count = Counter(numbers)
    max_count = max(list(count.values()))
    mode_values = [num for num, freq in count.items() if freq == max_count]
    return mode_values

def find_smallest_positive(numbers):
    positive_numbers = [num for num in numbers if num > 0]
    if not positive_numbers:
        return None
    return min(positive_numbers)

def main():
    numbers = []
    while True:
        try:
            value = int(input(""Enter a decimal number (0 to stop): ""))
            if value == 0:
                break
            numbers.append(value)
        except ValueError:
            print(""Invalid input. Please enter a valid integer."")

    mode_result = get_mode(numbers)
    if mode_result:
        print(f""Mode of non-zero elements: {mode_result}"")
    else:
        print(""No non-zero integers entered."")

    smallest_positive = find_smallest_positive(numbers)
    if smallest_positive is not None:
        print(f""Smallest positive integer: {smallest_positive}"")
    else:
        print(""No positive integers found."")

if __name__ == ""__main__"":
    main()
