```python
import json
from random import choice, randint

class ConnectionRequest:
    def __init__(self, src_address, flags):
        self.src_address = src_address
        self.flags = flags

class JsonHandler:
    class FactoryRegistry:
        @staticmethod
        def create_connection_request(src_address=None, unique=True, flag_probabilities={}):
            if not src_address:
                src_address = generateRandomString()
            flags = {}
            for flag in flag_probabilities.keys():
                if randint(0, 1) < flag_probabilities[flag]:
                    flags[flag] = True
                else:
                    flags[flag] = False
            return ConnectionRequest(src_address, flags)

    @staticmethod
    def create_json_array(array_size, unique=True, src_address_uniqueness=1.0, flag_probabilities={}, sequence_order_randomness=False):
        json_array = []
        addresses = set()
        for _ in range(array_size):
            while True:
                src_address = generateRandomString() if randint(0, 100) < (src_address_uniqueness * 100) else choice(list(addresses))
                if unique and src_address not in addresses:
                    addresses.add(src_address)
                    break
            connection_request = JsonHandler.FactoryRegistry.create_connection_request(src_address, unique, flag_probabilities)
            json_array.append(connection_request.__dict__)
        if sequence_order_randomness:
            shuffle(json_array)
        return json.dumps(json_array, indent=4)

# Example usage
array_size = 5
unique = True
src_address_uniqueness = 0.8
flag_probabilities = {'FLAG_A': 0.3, 'FLAG_B': 0.7}
sequence_order_randomness = True

json_output = JsonHandler.create_json_array(array_size, unique, src_address_uniqueness, flag_probabilities, sequence_order_randomness)
print(json_output)
