import statistics

def get_mode(numbers):
    try:
        return statistics.mode([num for num in numbers if num != 0])
    except statistics.StatisticsError:
        return ""No mode found among non-zero values.""

def find_smallest_positive(numbers):
    positive_numbers = [num for num in numbers if num > 0]
    try:
        return min(positive_numbers)
    except ValueError:
        return ""No positive integers found.""

def main():
    numbers = []
    while True:
        user_input = input(""Enter a decimal number (or 0 to stop): "")
        try:
            value = float(user_input)
            if value == 0:
                break
            numbers.append(value)
        except ValueError:
            print(""Invalid input. Please enter a valid decimal number."")

    mode_result = get_mode(numbers)
    smallest_positive_result = find_smallest_positive(numbers)

    print(f""Mode of non-zero values: {mode_result}"")
    print(f""Smallest positive integer: {smallest_positive_result}"")

if __name__ == ""__main__"":
    main()
