# RandomColorGenerator class in Python
class RandomColorGenerator:
    def __init__(self, min_value=0, max_value=255):
        self.min_value = min_value
        self.max_value = max_value

    def generate_random_int(self, min_val=None, max_val=None):
        return random.randint(min_val or self.min_value, max_val or self.max_value)

    @property
    def r(self):
        return self.generate_random_int()

    @property
    def g(self):
        return self.generate_random_int()

    @property
    def b(self):
        return self.generate_random_int()

    def generate_color(self):
        return (self.r, self.g, self.b)

# Example usage
