from Crypto.Cipher import AES, PKCS1_OAEP
from Crypto.PublicKey import RSA
from Crypto.Random import get_random_bytes
import base64

class EncryptionService:
    def __init__(self):
        self.cache = {}

    def encrypt(self, data, salt, algorithm='AES', key_size=256, return_length=None):
        if not data or not salt:
            raise ValueError(""Data and salt must not be null or empty"")

        if algorithm == 'AES':
            key = self._get_key(key_size)
            data += salt
            iv = get_random_bytes(AES.block_size)
            cipher = AES.new(key, AES.MODE_CBC, iv)
            encrypted_data = cipher.encrypt(data.encode('utf-8'))
            return base64.b64encode(iv + encrypted_data)[:return_length] if return_length else base64.b64encode(encrypted_data)
        elif algorithm == 'RSA':
            key_pair = RSA.generate(2048)  # Fixed key size for simplicity
            encryptor = PKCS1_OAEP.new(key_pair.publickey())
            encrypted_data = encryptor.encrypt(data.encode('utf-8'))
            return base64.b64encode(encrypted_data)
        else:
            raise ValueError(""Unsupported algorithm"")

    def _get_key(self, key_size):
        if key_size not in [128, 192, 256]:
            raise ValueError(""Unsupported AES key size"")

        salt = self.cache.get(f'aes_{key_size}_salt')
        if not salt:
            salt = get_random_bytes(16)  # Fixed salt length for simplicity
            self.cache[f'aes_{key_size}_salt'] = salt

        return (get_random_bytes(key_size // 8), salt)

# Example usage:
encryption_service = EncryptionService()
encrypted_data = encryption_service.encrypt(""Hello, World!"", ""my_salt"", algorithm='AES', key_size=256, return_length=None)
print(encrypted_data.decode('utf-8'))
```

