def traverse_graph(graph, property_check, callback=None):
    results = []

    def dfs(node):
        if property_check(node):
            results.append(node)
        if callback and callback(node):
            return
        for neighbor in graph[node]:
            dfs(neighbor)

    # Start DFS from each node to ensure all nodes are visited
    for node in graph:
        dfs(node)

    return results
