import time

class TrieNode:
    def __init__(self):
        self.children = {}
        self.end_of_word = False
        self.count = 0

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
            node.count += 1

    def find_anagrams(self, words):
        anagram_counts = {}
        result_pairs = []

        start_time = time.time()

        for i, word in enumerate(words):
            sorted_word_key = ''.join(sorted(word))
            if sorted_word_key not in anagram_counts:
                anagram_counts[sorted_word_key] += 1
                if anagram_counts[sorted_word_key] == 2:
                    result_pairs.append((word, words[i-1]))
                    del anagram_counts[sorted_word_key]

        end_time = time.time()

        microseconds_taken = (end_time - start_time) * 10**6

        return result_pairs, microseconds_taken

def main():
    words_list = [""listen"", ""silent"", ""tinsel"", ""elints"", ""pots"", ""spot""]

    trie = Trie()

    for word in words_list:
        trie.insert(word)

    result, microseconds_taken= trie.find_anagrams(words_list)

    print(""Distinct Anagram Pairs:"")
    for pair in result:
        print(f""{pair[0]} and {pair[1]}"")

    print(f""\nNumber of microseconds taken: {microseconds_taken}"")

if __name__ == ""__main__"":
    main()
