# Import necessary libraries
from flask import Flask, request, jsonify
import jwt
import datetime
from functools import wraps

app = Flask(__name__)

# Secret key for JWT
SECRET_KEY = 'your_secret_key_here'

# Middleware to check JWT token
def requires_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization')
        if not auth_header:
            return jsonify({""message"": ""Authentication header is missing""}), 401

        parts = auth_header.split()

        if parts[0].lower() != 'bearer':
            return jsonify({""message"": ""Invalid authorization type""}), 401

        elif len(parts) == 1:
            return jsonify({""message"": ""Token is missing""}), 401

        elif len(parts) > 2:
            return jsonify({""message"": ""Authorization header must be 'Bearer <token>'""}), 401

        token = parts[1]
        try:
            payload = jwt.decode(token, SECRET_KEY, algorithms=[""HS256""])
            if 'role' not in payload:
                return jsonify({""message"": ""No role claim in the token""}), 403
        except jwt.ExpiredSignatureError:
            return jsonify({""message"": ""Token has expired""}), 401
        except jwt.InvalidTokenError:
            return jsonify({""message"": ""Invalid token""}), 401

        return f(*args, **kwargs)

    return decorated

# Route for protected endpoint
@app.route('/protected', methods=['GET'])
@requires_auth
def protected():
    payload = request.headers.get('Authorization').split()[1]
    data = jwt.decode(payload, SECRET_KEY, algorithms=[""HS256""])
    return jsonify({""message"": ""Access granted"", ""user_role"": data['role']})

# Route for generating JWT token
@app.route('/login', methods=['POST'])
def login():
    auth_data = request.get_json()

    if not auth_data or 'username' not in auth_data or 'password' not in auth_data:
        return jsonify({""message"": ""Invalid request""}), 400

    # Dummy user verification logic
    username = auth_data['username']
    password = auth_data['password']

    if username == 'admin' and password == 'admin':
        payload = {
            'user': username,
            'role': 'admin',
            'exp': datetime.datetime.utcnow() + datetime.timedelta(hours=1)
        }
        token = jwt.encode(payload, SECRET_KEY, algorithm=""HS256"")
        return jsonify({""token"": token})
    else:
        return jsonify({""message"": ""Invalid credentials""}), 401

if __name__ == '__main__':
    app.run(debug=True)
