import random

def estimate_pi(num_points):
    if num_points < 0:
        raise ValueError(""Number of points must be non-negative"")

    inside_circle = 0

    for _ in range(num_points):
        x, y = random.random(), random.random()
        if x**2 + y**2 <= 1:
            inside_circle += 1

    return 4 * (inside_circle / num_points)

