import random
from typing import List

class DscpManager:
    def __init__(self):
        self.dscp_array = []

    def add_structure(self, protocol_id: int, dscp: int, class_id: int):
        if not (0 <= protocol_id <= 65535) or not (0 <= dscp <= 63) or not (0 <= class_id <= 65535):
            raise ValueError(""Invalid values for protocol ID, DSCP value, or class ID."")
        new_structure = {'protocol_id': protocol_id, 'dscp': dscp, 'class_id': class_id}
        self.dscp_array.append(new_structure)

    def generate_random_structure(self):
        protocol_id = random.randint(10000, 65432)
        dscp = random.randint(16, 63)
        class_id = random.randint(128, 65432)
        return {'protocol_id': protocol_id, 'dscp': dscp, 'class_id': class_id}

    def validate_structures(self) -> bool:
        valid = True
        for structure in self.dscp_array:
            if structure['protocol_id'] > 65535 or structure['dscp'] > 63 or structure['class_id'] > 65535:
                valid = False
                break
        return valid

    def generate_array(self) -> List[dict]:
        if not self.validate_structures():
            raise ValueError(""Invalid structures found."")

        return [self.generate_random_structure() for _ in range(10)]

# Usage example
