def find_mode(numbers):
    from collections import Counter
    count = Counter(numbers)
    max_count = max(list(count.values()))
    mode = [num for num, freq in count.items() if freq == max_count]
    return mode

def find_smallest_positive(numbers):
    positives = [num for num in numbers if num > 0]
    if not positives:
        return None
    return min(positives)

def main():
    numbers = []

    while True:
        try:
            user_input = float(input(""Enter a decimal number (enter 0 to stop): ""))
            if user_input == 0:
                break
            numbers.append(user_input)
        except ValueError:
            print(""Invalid input. Please enter a valid decimal number."")

    non_zero_numbers = [num for num in numbers if num != 0]

    if non_zero_numbers:
        mode_result = find_mode(non_zero_numbers)
        print(f""Mode(s): {mode_result}"")
    else:
        print(""No non-zero integers entered."")

    smallest_positive = find_smallest_positive(numbers)
    if smallest_positive is not None:
        print(f""The smallest positive integer is: {smallest_positive}"")
    else:
        print(""No positive integers found."")

if __name__ == ""__main__"":
    main()
