The script should output usage instructions if no valid input arguments are provided and should gracefully handle errors related to missing or invalid configuration files or data entries.",121,,"['```python
import argparse
import os

def parse_config_file(file_path):
    config = {}
    try:
        with open(file_path, 'r') as file:
            for line in file:
                key, value = line.strip().split('=')
                config[key.strip()] = value.strip()
    except FileNotFoundError:
        print(f""Error: Configuration file '{file_path}' not found."")
    except PermissionError:
        print(f""Error: Unable to read the configuration file '{file_path}'."")
    return config

def validate_config(config):
    default_settings = {
        'port': 80,
        'document_root': '/var/www/html',
        'log_file': '/var/log/webserver.log'
    }

    for key, value in default_settings.items():
        if key not in config:
            config[key] = value
        else:
            if key == 'port' and (not value.isdigit() or int(value) < 1 or int(value) > 65535):
                print(f""Invalid port number '{value}'. Using default port {default_settings['port']}."")
                config[key] = str(default_settings['port'])
            elif key in ['document_root', 'log_file']:
                if not os.path.exists(value):
                    print(f""Path '{value}' does not exist. Using default path for {key}."")
                    config[key] = default_settings[key]

    return config

def main():
    parser = argparse.ArgumentParser(description=""Configure a web server."")
    parser.add_argument('--config', help='Path to the configuration file.')
