import hashlib
import os
from datetime import datetime

def validate_input(input_string):
    if not input_string:
        raise ValueError(""Input string cannot be empty"")
    return input_string.strip()

def trim_whitespace(input_string):
    return input_string.strip()

def append_characters(input_string, max_length, character):
    if len(input_string) < max_length:
        return input_string + character * (max_length - len(input_string))
    return input_string

def read_file_efficiently(file_path):
    with open(file_path, 'rb') as file:
        return file.read()

def calculate_sha256_hash(file_data):
    sha256 = hashlib.sha256()
    sha256.update(file_data)
    return sha256.hexdigest()

def extract_metadata(file_path):
    metadata = {}
    try:
        stat_info = os.stat(file_path)
        metadata['creation_date'] = datetime.fromtimestamp(stat_info.st_ctime).strftime('%Y-%m-%d %H:%M:%S')
        metadata['last_modified'] = datetime.fromtimestamp(stat_info.st_mtime).strftime('%Y-%m-%d %H:%M:%S')
    except Exception as e:
        print(f""Error extracting metadata: {e}"")
    return metadata

def encrypt_metadata(metadata, key):
    encrypted_metadata = {}
    for key, value in metadata.items():
        if isinstance(value, str):
            encrypted_value = ''.join([chr((ord(c) + ord(key[i % len(key)])) % 256) for i, c in enumerate(value)])
            encrypted_metadata[key] = encrypted_value
        else:
            encrypted_metadata[key] = value
    return encrypted_metadata

def store_securely(encrypted_data):
    with open('secure_storage.txt', 'w') as file:
        file.write(str(encrypted_data))

