        print(f""Error fetching data: {e}"")
        return None

    soup = BeautifulSoup(response.text, 'html.parser')
    trending_repos = []
    for repo in soup.find_all('h1', class_='lh-condensed'):
        try:
            name = repo.find_next('a').text.strip()
            stars = int(repo.find_next('span', class_='d-inline-block mr-3').text.strip().replace(',', ''))
            forks = int(repo.find_next('span', class_='d-inline-block mr-3').next_sibling.text.strip().replace(',', ''))
            last_commit = repo.find_next('relative-time')['datetime']
            trending_repos.append({
                'name': name,
                'stars': stars,
                'forks': forks,
                'last_commit': last_commit
            })
        except AttributeError as e:
            print(f""Error parsing repository data: {e}"")

    return trending_repos

def save_to_json(repos, sort_by='stars'):
    if not repos:
        return

    sorted_repos = sorted(repos, key=lambda x: x[sort_by], reverse=True)
    with open('github_trends.json', 'w') as f:
        json.dump(sorted_repos, f, indent=4)

def main():
    repos = fetch_github_trends()
    if repos:
        save_to_json(repos)

if __name__ == '__main__':
    main()
