    def generate_matrix(self):
        return np.random.randint(*self.red_range, size=(3, 3))

    def add_matrices(self, mat1: np.ndarray):
        return mat1 + mat1

    def multiply_matrix_by_scalar(self, mat: np.ndarray):
        scalar = 2
        return mat * scalar

    def calculate_determinant(self, mat: np.ndarray):
        return np.linalg.det(mat)

    def invert_matrix(self, mat: np.ndarray):
        return np.linalg.inv(mat) if np.linalg.det(mat) != 0 else None

    def find_eigenvalues_and_eigenvectors(self, mat: np.ndarray):
        return np.linalg.eig(mat)

    def encrypt_matrix(self, matrix: np.ndarray):
        data = self.generate_matrix().tostring()
        cipher = AES.new(self.key.encode(), AES.MODE_CBC, self.iv)
        encrypted_data = cipher.encrypt(pad(data, AES.block_size))
        return b64encode(encrypted_data).decode()

    def decrypt_matrix(self, encrypted_data: str):
        iv = self.iv
        key = self.key
        encrypted_data = b64decode(encrypted_data)
        cipher = AES.new(key.encode(), AES.MODE_CBC, iv)
        decrypted_data = unpad(cipher.decrypt(encrypted_data), AES.block_size)
        return np.frombuffer(decrypted_data, dtype=int).reshape((3, 3))
