import argparse
import os
import yaml

def validate_port(port):
    try:
        port = int(port)
        if not 1024 < port < 65536:
            raise ValueError(""Port number must be within the range 1024 to 65535."")
        return True
    except ValueError:
        return False

def validate_path(path):
    return os.path.exists(path)

def parse_args():
    parser = argparse.ArgumentParser(description=""Configure a web server setup."")
    parser.add_argument(""-c"", ""--config"", type=str, help=""Path to the configuration file"")
    args = parser.parse_args()
    return args

def read_config_file(config_path):
    if not os.path.isfile(config_path):
        raise FileNotFoundError(f""Configuration file {config_path} not found."")

    with open(config_path, 'r') as file:
        config_data = yaml.safe_load(file)

        if not isinstance(config_data, dict):
            raise ValueError(""Invalid configuration format. Expecting a dictionary."")

        settings = {}

        if 'server' in config_data:
            server_settings = config_data['server']

            for key, value in server_settings.items():
                if key == 'port':
                    settings['port'] = value if validate_port(value) else None
                elif key == 'doc_root':
                    settings['doc_root'] = value if validate_path(value) else None
                elif key == 'log_file':
                    settings['log_file'] = value if validate_path(value) else None

        return settings

def main():
    args = parse_args()

    try:
        config_settings = read_config_file(args.config)

        # Print summary of parsed configuration with default values for missing entries
        print(f""Config Summary:"")

        for key, value in config_settings.items():
            print(f""{key}: {value or '(default)'}"")

    except (FileNotFoundError, ValueError) as e:
        print(f""Error: {str(e)}"")

if __name__ == ""__main__"":
    main()
