2,"Develop a Python program that constructs a binary search tree (BST) of custom objects, each having a 'String' symbol and an 'Integer' value. Populate the BST with randomly generated data, where symbols are alphanumeric strings and values are integers within a predefined range. Accept an array of integers representing the number of elements for each value range and an array of strings for the symbol types. Upon successful creation, traverse the BST in-order to display the symbols and values for each node. Return the populated BST without additional information or comments.",338,,"['```python
import random

class Node:
    def __init__(self, symbol, value):
        self.symbol = symbol
        self.value = value
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, symbol, value):
        if self.root is None:
            self.root = Node(symbol, value)
        else:
            self._insert_recursive(self.root, symbol, value)

    def _insert_recursive(self, node, symbol, value):
        if value < node.value:
            if node.left is None:
                node.left = Node(symbol, value)
            else:
                self._insert_recursive(node.left, symbol, value)
        elif value > node.value:
            if node.right is None:
                node.right = Node(symbol, value)
            else:
                self._insert_recursive(node.right, symbol, value)

    def inorder_traversal(self):
        result = []
        self._inorder_traversal_recursive(self.root, result)
        return result

    def _inorder_traversal_recursive(self, node, result):
        if node is not None:
            self._inorder_traversal_recursive(node.left, result)
            result.append((node.symbol, node.value))
            self._inorder_traversal_recursive(node.right, result)

def populate_bst(value_counts, symbol_types):
    bst = BinarySearchTree()
    for value_range in value_counts:
        start = 10
        end = start + value_range - 1
        for _ in range(end - start + 1):
            value = random.randint(start, end)
            symbol_type = random.choice(symbol_types)
            symbol = ''.join(random.choices('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ', k=5))
            bst.insert(symbol, value)
    return bst

def main():
    value_counts = [10, 20, 30]
    symbol_types = ['Alpha', 'Numeric']
    bst = populate_bst(value_counts, symbol_types)
    for symbol, value in bst.inorder_traversal():
        print(f""Symbol: {symbol}, Value: {value}"")

if __name__ == ""__main__"":
    main()
